package com.bank.elk.log;

import java.time.Instant;

// One structured log document, as it would be stored in Elasticsearch.
public class LogLine {
    private final Instant timestamp;
    private final String service;
    private final String level;
    private final String correlationId;
    private final String message;

    public LogLine(String service, String level, String correlationId, String message) {
        this.timestamp = Instant.now();
        this.service = service;
        this.level = level;
        this.correlationId = correlationId;
        this.message = message;
    }

    public String getCorrelationId() { return correlationId; }

    // Render like a JSON log document Kibana would display.
    @Override
    public String toString() {
        return "{\"ts\":\"" + timestamp + "\",\"service\":\"" + service
             + "\",\"level\":\"" + level + "\",\"correlationId\":\"" + correlationId
             + "\",\"msg\":\"" + message + "\"}";
    }
}
