package com.bank.elk.log;

import java.util.ArrayList;
import java.util.List;

// In-memory stand-in for Elasticsearch: every service writes here.
public class LogStore {
    private final List<LogLine> documents = new ArrayList<>();

    public void index(LogLine line) { documents.add(line); } // "index a document"
    public List<LogLine> all() { return documents; }
}
