package com.bank.elk.service;

import com.bank.elk.log.LogLine;
import com.bank.elk.log.LogStore;
import com.bank.elk.trace.CorrelationContext;
import java.util.UUID;

// Entry point: assigns the correlation ID and propagates it downstream.
public class GatewayService {
    private final LogStore store;
    private final TransferService transfer;

    public GatewayService(LogStore store, TransferService transfer) {
        this.store = store;
        this.transfer = transfer;
    }

    public void handleTransfer(String from, String to, String amount) {
        // New request → mint a correlation ID and put it into the context.
        String correlationId = "cid-" + UUID.randomUUID().toString().substring(0, 8);
        CorrelationContext.set(correlationId);
        store.index(new LogLine("gateway", "INFO", correlationId,
                "received transfer " + from + "->" + to + " amount " + amount));
        // Propagate the SAME id downstream (header in real life).
        transfer.transfer(correlationId, from, to, amount);
        CorrelationContext.clear();
    }
}
