package com.bank.elk.service;

import com.bank.elk.log.LogLine;
import com.bank.elk.log.LogStore;

public class TransferService {
    private final LogStore store;
    private final FraudService fraud;
    private final AccountService accounts;

    public TransferService(LogStore store, FraudService fraud, AccountService accounts) {
        this.store = store;
        this.fraud = fraud;
        this.accounts = accounts;
    }

    public void transfer(String correlationId, String from, String to, String amount) {
        store.index(new LogLine("transfer-service", "INFO", correlationId,
                "validating transfer from " + from));
        boolean flagged = fraud.check(correlationId, from, amount);  // propagate id
        if (flagged) {
            store.index(new LogLine("transfer-service", "ERROR", correlationId,
                    "transfer BLOCKED by fraud rules"));
            return;
        }
        accounts.debitCredit(correlationId, from, to, amount);       // propagate id
        store.index(new LogLine("transfer-service", "INFO", correlationId,
                "transfer COMPLETED"));
    }
}
