package com.bank.elk.service;

import com.bank.elk.log.LogLine;
import com.bank.elk.log.LogStore;
import java.math.BigDecimal;

public class FraudService {
    private final LogStore store;
    public FraudService(LogStore store) { this.store = store; }

    // Flags transfers above a threshold for this demo.
    public boolean check(String correlationId, String from, String amount) {
        boolean flagged = new BigDecimal(amount).compareTo(new BigDecimal("500000")) > 0;
        store.index(new LogLine("fraud-service", flagged ? "WARN" : "INFO", correlationId,
                "fraud score for " + from + " flagged=" + flagged));
        return flagged;
    }
}
