package com.bank.elk.kibana;

import com.bank.elk.log.LogLine;
import com.bank.elk.log.LogStore;
import java.util.List;
import java.util.logging.Logger;

// Reproduces Kibana's Discover view: filter all docs by one correlation ID.
public class KibanaQuery {
    private static final Logger log = Logger.getLogger(KibanaQuery.class.getName());
    private final LogStore store;

    public KibanaQuery(LogStore store) { this.store = store; }

    public void searchByCorrelationId(String correlationId) {
        log.info(() -> "Kibana filter: correlationId = " + correlationId);
        List<LogLine> hits = store.all().stream()
                .filter(l -> l.getCorrelationId().equals(correlationId))
                .toList();
        hits.forEach(l -> log.info(l.toString()));
        log.info(() -> hits.size() + " log lines across all services for this request");
    }
}
