package com.bank.elk;

import com.bank.elk.kibana.KibanaQuery;
import com.bank.elk.log.LogStore;
import com.bank.elk.service.*;
import com.bank.elk.trace.CorrelationContext;

public class ElkDemo {
    public static void main(String[] args) {
        LogStore store = new LogStore(); // stands in for Elasticsearch
        AccountService accounts = new AccountService(store);
        FraudService fraud = new FraudService(store);
        TransferService transfer = new TransferService(store, fraud, accounts);
        GatewayService gateway = new GatewayService(store, transfer);

        // Successful transfer: Rajesh -> Priya, 50,000.
        gateway.handleTransfer("SAV2001", "CUR3001", "50000");

        // Failed transfer: large amount flagged by fraud.
        gateway.handleTransfer("SAV2001", "CUR3001", "900000");

        // Grab the correlation ID of the LAST (failed) request to trace it.
        String failedCid = store.all().stream()
                .filter(l -> l.toString().contains("BLOCKED"))
                .findFirst().map(l -> l.getCorrelationId()).orElse("");

        new KibanaQuery(store).searchByCorrelationId(failedCid);
        CorrelationContext.clear();
    }
}
